import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> dict(side, price, remaining, arrival, status)
    buy_heap = []   # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)

    def get_top(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            info = orders_info.get(oid)
            if info is None or info['status'] != 'resting' or info['remaining'] <= 0:
                heapq.heappop(heap)
                continue
            return item
        return None

    def do_match(incoming_id, side, price, qty, is_market):
        opposite = sell_heap if side == 'buy' else buy_heap
        while qty > 0:
            top = get_top(opposite)
            if top is None:
                break
            if side == 'buy':
                top_price = top[0]
                if not is_market and top_price > price:
                    break
            else:
                top_price = -top[0]
                if not is_market and top_price < price:
                    break

            resting_id = top[2]
            resting_info = orders_info[resting_id]
            trade_qty = min(qty, resting_info['remaining'])
            resting_info['remaining'] -= trade_qty
            qty -= trade_qty
            trade_price = resting_info['price']

            if side == 'buy':
                trades.append([incoming_id, resting_id, trade_price, trade_qty])
            else:
                trades.append([resting_id, incoming_id, trade_price, trade_qty])

            if resting_info['remaining'] == 0:
                resting_info['status'] = 'filled'
                heapq.heappop(opposite)
            # else keep it at top for next iteration (still has remaining qty)

        return qty

    for arrival, order in enumerate(orders):
        otype = order[0]

        if otype == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and info['status'] == 'resting':
                info['status'] = 'cancelled'
            continue

        if otype == 'limit':
            _, oid, side, price, qty = order
            remaining = do_match(oid, side, price, qty, False)
            if remaining > 0:
                orders_info[oid] = {
                    'side': side,
                    'price': price,
                    'remaining': remaining,
                    'arrival': arrival,
                    'status': 'resting'
                }
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, arrival, oid))
                else:
                    heapq.heappush(sell_heap, (price, arrival, oid))
            else:
                orders_info[oid] = {
                    'side': side,
                    'price': price,
                    'remaining': 0,
                    'arrival': arrival,
                    'status': 'filled'
                }

        elif otype == 'ioc':
            _, oid, side, price, qty = order
            remaining = do_match(oid, side, price, qty, False)
            orders_info[oid] = {
                'side': side,
                'price': price,
                'remaining': 0,
                'arrival': arrival,
                'status': 'filled' if remaining < qty else 'cancelled'
            }

        elif otype == 'market':
            _, oid, side, qty = order
            remaining = do_match(oid, side, None, qty, True)
            orders_info[oid] = {
                'side': side,
                'price': None,
                'remaining': 0,
                'arrival': arrival,
                'status': 'filled' if remaining < qty else 'cancelled'
            }

    return trades

